create table if not exists public.kw_plz3_centroids (
  plz3 text primary key check (plz3 ~ '^[0-9]{3}$'),
  lat double precision not null,
  lng double precision not null
);

alter table public.kw_plz3_centroids enable row level security;

drop policy if exists "PLZ3: public read" on public.kw_plz3_centroids;
create policy "PLZ3: public read" on public.kw_plz3_centroids for select using (true);

grant select on public.kw_plz3_centroids to anon, authenticated;
grant all on public.kw_plz3_centroids to service_role;

