on conflict (plz3) do update set lat = excluded.lat, lng = excluded.lng;

create or replace function public.kw_plz_distance_km(p_a text, p_b text)
returns numeric
language sql
stable
set search_path = public, pg_catalog
as $$
  select round((6371 * 2 * asin(sqrt(
           power(sin(radians(b.lat - a.lat) / 2), 2)
           + cos(radians(a.lat)) * cos(radians(b.lat))
             * power(sin(radians(b.lng - a.lng) / 2), 2)
         )))::numeric, 1)
  from public.kw_plz3_centroids a, public.kw_plz3_centroids b
  where a.plz3 = left(p_a, 3) and b.plz3 = left(p_b, 3);
$$;

grant execute on function public.kw_plz_distance_km(text, text) to anon, authenticated, service_role;
